/// Install the macOS deferred should-terminate owner. The future must
/// positively confirm exit; cancellation/refusal must resolve false. Native
/// requests are coalesced while pending, and callbacks/replies are deferred
/// outside App borrows. This replaces the prior owner, not quit observers.
/// Other platforms retain their existing termination behavior.
pub fn on_should_quit<Fut>(
    &self,
    mut callback: impl FnMut(&mut App) -> Fut + 'static,
) where
    Fut: 'static + Future<Output = bool>,
{
    let app = self.this.clone();
    self.platform.on_should_quit(Box::new(move || {
        let Some(app) = app.upgrade() else {
            return std::future::ready(false).boxed_local();
        };
        let Ok(mut app) = app.try_borrow_mut() else {
            return std::future::ready(false).boxed_local();
        };
        app.update(|cx| callback(cx)).boxed_local()
    }));
}

